// 返回原命令而非直接替NPC签署；实际采用和计划结果同属中央保存点。
#include "treaty_passage_director.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {
Outcome<std::optional<DecisionProposal>> propose_director_treaty_passage(const TreatyPassageContext& c,const KnownSubjectView& known,const DirectorPolicy& policy,const DecisionProposal& base){
 if(!base.transition||base.subject_id!=known.actor_id||known.tick!=c.diplomacy.common.tick()||known.revision!=c.diplomacy.common.revision()||base.transition->expected_revision!=known.revision)return {false,{},common_failure("InvalidTreatyDirectorProposal",known.actor_id,ErrorKind::internal).error};
 auto candidates=propose_treaty_passage_npc(c,known.actor_id);if(!candidates.ok)return {false,{},candidates.error};
 for(auto& command:candidates.value){if(command.authority.organization_id!=policy.organization_id)continue;auto result=base;auto next=std::make_shared<DirectorTransition>(*base.transition);next->template_id="treaty_ratification";next->goal_ref=command.offer_id;next->current_action_id.reset();next->next_step_index=0;next->phase=PlanPhase::completed;next->wait_reason.clear();result.reason_fact_id=command.knowledge_source_fact_id;result.command=std::make_shared<const CommandPayload>(CommandPayload{"treaty_passage_sign",TreatyPassageCommand{command}});result.transition=std::move(next);return {true,std::move(result),{}};}
 return {true,std::nullopt,{}};
}
Status validate_treaty_passage_director(const DirectorCatalog& catalog,const DirectorState& state,const TreatyPassageCatalog* treaty,const TreatyPassageState* history,const OrganizationCatalog& organizations){
 const bool enabled=treaty&&treaty->enabled;if(catalog.treaty_passage!=enabled)return common_failure("TreatyDirectorProfileMismatch");
 const auto& policies=catalog.dynamic_subjects?catalog.policies:catalog.subjects;
 for(const auto& row:policies.rows()){const auto& policy=row.second;if(std::find(policy.templates.begin(),policy.templates.end(),DirectorTemplate::treaty_ratification)==policy.templates.end())continue;if(!enabled||!catalog.dynamic_subjects)return common_failure("TreatyDirectorProfileRequired",row.first);bool mandated=false;for(const auto& provision:treaty->provisions.rows())for(const auto& office_id:provision.second.npc_ratifier_office_ids){const auto* office=organizations.offices.find(office_id);if(office&&office->organization_id==policy.organization_id)mandated=true;}if(!mandated)return common_failure("TreatyDirectorMandateMissing",row.first);}
 const auto check=[&](const auto& plans)->Status{for(const auto& row:plans.rows()){const auto& plan=row.second;if(plan.template_id!="treaty_ratification")continue;if(plan.subject.kind!=SubjectKind::actor)return common_failure("TreatyDirectorActorSubjectRequired",row.first);if(!enabled||!history)return common_failure("TreatyDirectorProfileRequired",row.first);const auto* policy=catalog.dynamic_subjects?policies.find(plan.policy_id):policies.find(plan.subject.id);if(!policy||std::find(policy->templates.begin(),policy->templates.end(),DirectorTemplate::treaty_ratification)==policy->templates.end())return common_failure("TreatyDirectorPolicyMismatch",row.first);if(plan.phase==PlanPhase::completed){bool matched=false;for(const auto& signature:history->signatures.rows())if(signature.second.offer_id==plan.goal_ref&&signature.second.authority.actor_id==plan.subject.id&&signature.second.authority.organization_id==policy->organization_id){const auto* provision=treaty->provisions.find(signature.second.terms_id);if(provision&&std::find(provision->npc_ratifier_office_ids.begin(),provision->npc_ratifier_office_ids.end(),signature.second.authority.office_id)!=provision->npc_ratifier_office_ids.end())matched=true;}if(!matched)return common_failure("TreatyDirectorSignatureMissing",row.first);}}return common_success();};auto valid=check(state.plans);return valid.ok?check(state.archived_plans):valid;
}
}
